import java.util.List;

interface Payment { long cents(); }
record CardPayment(long cents) implements Payment {}

// Java can't say "T only comes out" on the declaration
interface Source<T> {
    T next();
}

class Feeds {
    // every method that should accept subtypes must remember ? extends
    static long total(Source<? extends Payment> source, int n) {
        long sum = 0;
        for (int i = 0; i < n; i++) sum += source.next().cents();
        return sum;
    }

    static long sum(List<? extends Payment> payments) {
        return payments.stream().mapToLong(Payment::cents).sum();
    }

    // forget it once and the method is stricter than it needs to be
    static long strict(Source<Payment> source) { return source.next().cents(); }
}

